    .krh .krh-note li{margin-left:16px}
    .krh .krh-note li+li{margin-top:2px}
    .krh .krh-nowrap{white-space:nowrap}
    .krh .krh-actions{display:flex;gap:8px;margin-top:14px}
    .krh .krh-btn{flex:1;height:44px;border:1.5px solid var(--krh-line);border-radius:12px;background:#fff;color:var(--krh-text);
      font-size:14px;font-weight:600;cursor:pointer;transition:background .2s,transform .1s}
    .krh .krh-btn:hover{background:#f4f6fa}
    .krh .krh-btn:active{transform:scale(.98)}
    .krh .krh-btn.krh-primary{border-color:var(--krh-accent);background:var(--krh-accent);color:#fff}
    .krh .krh-btn.krh-primary:hover{background:#2f5fe0}
    @media (max-width:420px){.krh{padding:18px;border-radius:16px}.krh .krh-big{font-size:34px}.krh .krh-in{font-size:17px}
      .krh .krh-table th,.krh .krh-table td{padding:8px 8px}.krh .krh-chip{padding:0 10px}}
    @media (prefers-reduced-motion:reduce){.krh .krh-result,.krh .krh-in,.krh .krh-btn,.krh .krh-chip,.krh .krh-seg button{transition:none}}
  </style>

  <p class="krh-title">육아기 근로시간 단축 급여 계산기</p>
  <p class="krh-desc">월 통상임금과 줄일 근무시간을 넣으면 회사 월급과 정부 단축급여, 합쳐서 한 달에 얼마인지 바로 계산돼요. <span class="krh-nowrap" data-basis>2026년 기준</span></p>

  <div class="krh-seg" role="group" aria-label="기준 연도">
    <button type="button" class="krh-on" data-year="2026" aria-pressed="true">2026년</button>
    <button type="button" data-year="2027" aria-pressed="false">2027년</button>
  </div>
  <p class="krh-warn" data-year-note hidden></p>

  <label class="krh-label" for="krh-wage"><span>월 통상임금 <small>(세전, 단축 전)</small></span></label>
  <div class="krh-field"><input class="krh-in" id="krh-wage" data-wage inputmode="numeric" placeholder="3,000,000"><span class="krh-unit">원</span></div>
  <p class="krh-hint">기본급과 매달 고정으로 받는 수당을 더한 금액이에요. 단축 시작일 기준이에요.</p>

  <div class="krh-row">
    <div class="krh-col">
      <label class="krh-label" for="krh-before"><span>단축 전 주 근로시간</span></label>
      <div class="krh-field"><input class="krh-in" id="krh-before" data-before inputmode="decimal" maxlength="4" value="40" placeholder="40"><span class="krh-unit">시간</span></div>
    </div>
    <div class="krh-col">
      <label class="krh-label" for="krh-after"><span>단축 후 주 근로시간</span></label>
      <div class="krh-field"><input class="krh-in" id="krh-after" data-after inputmode="decimal" maxlength="4" placeholder="30"><span class="krh-unit">시간</span></div>
    </div>
  </div>
  <div class="krh-chips" data-after-chips>
    <button type="button" class="krh-chip" data-a="35">주 35시간 (하루 1시간↓)</button>
    <button type="button" class="krh-chip" data-a="30">주 30시간 (하루 2시간↓)</button>
    <button type="button" class="krh-chip" data-a="25">주 25시간</button>
    <button type="button" class="krh-chip" data-a="20">주 20시간 (하루 4시간)</button>
    <button type="button" class="krh-chip" data-a="15">주 15시간</button>
  </div>
  <p class="krh-hint">단축 후에는 주 15시간 이상 35시간 이하로 일해야 해요. 단축 전 시간은 근로계약서의 주 소정근로시간이에요.</p>

  <label class="krh-label" for="krh-months"><span>단축 기간</span><small>1~36개월</small></label>
  <div class="krh-field"><input class="krh-in" id="krh-months" data-months inputmode="numeric" maxlength="2" value="12" placeholder="12"><span class="krh-unit">개월</span></div>
  <div class="krh-chips" data-month-chips>
    <button type="button" class="krh-chip" data-m="3">3개월</button>
    <button type="button" class="krh-chip" data-m="6">6개월</button>
    <button type="button" class="krh-chip" data-m="12">1년</button>
    <button type="button" class="krh-chip" data-m="24">2년</button>
    <button type="button" class="krh-chip" data-m="36">3년</button>
  </div>

  <p class="krh-msg" data-msg role="status" aria-live="polite"></p>

  <div class="krh-result" data-result aria-live="polite">
    <div class="krh-result-inner">
      <div class="krh-main">
        <p class="krh-main-label" data-main-label></p>
        <p class="krh-big" data-big></p>
        <p class="krh-badge" data-badge></p>
        <p class="krh-sub" data-sub></p>
      </div>
      <p class="krh-sec">한 달 예상 수입</p>
      <table class="krh-table"><tbody data-rows></tbody></table>
      <div class="krh-formula" data-formula></div>
      <ul class="krh-note">
        <li>단축급여는 고용보험에서 주고 세금이 붙지 않아요. 회사 월급은 통상임금을 근로시간 비율대로 줄인 참고값이라 실제 급여명세서와 다를 수 있어요.</li>
        <li data-long-note hidden>단축은 기본 1년이고, 쓰지 않은 육아휴직 기간의 2배를 더해 최대 3년까지 쓸 수 있어요.</li>
        <li>고용보험 피보험단위기간 180일 이상이 필요해요. 정확한 금액은 고용24나 고용센터에서 확인하세요.</li>
        <li>회사도 고용24에서 사업주 지원금(대체인력·업무분담 지원금 등)을 신청할 수 있으니 회사에 함께 알려 주세요.</li>
      </ul>
      <div class="krh-actions">
        <button type="button" class="krh-btn" data-reset>다시 입력</button>
        <button type="button" class="krh-btn krh-primary" data-copy>결과 복사</button>
      </div>
    </div>
  </div>

  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-krh]');
    if (!root || root.__krh) return;
    root.__krh = true;

    // ===== 바뀔 수 있는 값: 제도가 바뀌면 여기만 고치면 돼요 (README.md "매년 할 일" 참고) =====
    // 고용보험법 시행령 제104조의2 (대통령령 제35934호, 2026.1.1 시행). 2026.11.26 현재 2027년 변경 발표 없음.
    var R = {
      '2026': { basis: '2026년 기준', full: 10, cap1: 2500000, cap2: 1600000, rate2: 0.8, floor: 500000, note: '' },
      '2027': { basis: '2027년 (발표 전, 2026년 값)', full: 10, cap1: 2500000, cap2: 1600000, rate2: 0.8, floor: 500000,
                note: '2027년 단축급여 상한 변경은 2026년 11월 26일 현재 발표 전이라 2026년 값으로 계산해요. 바뀌면 고쳐 둘게요.' }
    };
    // ===== 바뀔 수 있는 값 끝 =====

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var wageI = $('[data-wage]'), beforeI = $('[data-before]'), afterI = $('[data-after]'), monthsI = $('[data-months]');
    var msg = $('[data-msg]'), result = $('[data-result]');
    var year = '2026', lastText = '';

    function comma(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function won(n) { return comma(Math.floor(n)) + '원'; }
    function man(n) { return (n % 10000 ? comma(n) + '원' : comma(n / 10000) + '만원'); }
    function hrs(h) { return (Math.round(h * 10) / 10) + '시간'; }
    function num(inp) { return +String(inp.value).replace(/\D/g, '') || 0; }
    function dec(inp) { var v = String(inp.value).trim(); return /^\d{1,2}(\.\d)?$/.test(v) ? +v : NaN; }
    function hide(text) { result.classList.remove('krh-show'); msg.textContent = text || ''; }
    function clamp(v, lo, hi) { return Math.min(Math.max(v, lo), hi); }

    function calc() {
      var c = R[year];
      var wRaw = wageI.value, bRaw = beforeI.value.trim(), aRaw = afterI.value.trim(), mRaw = monthsI.value;
      if (!wRaw && !aRaw) return hide('');
      var wage = num(wageI), before = dec(beforeI), after = dec(afterI), months = +mRaw;
      if (wRaw && !wage) return hide('월 통상임금을 입력해 주세요.');
      if (wage > 100000000) return hide('월 통상임금을 다시 확인해 주세요.');
      if (bRaw && (isNaN(before) || before <= 0 || before > 40)) return hide('단축 전 주 근로시간은 40시간 이하로 넣어 주세요 (소수점은 한 자리까지).');
      if (aRaw && (isNaN(after) || after < 15 || after > 35)) return hide('단축 후 근로시간은 주 15시간 이상 35시간 이하여야 해요.');
      if (bRaw && aRaw && after >= before) return hide('단축 후 근로시간이 단축 전보다 짧아야 해요.');
      if (mRaw && (months < 1 || months > 36)) return hide('단축 기간은 1~36개월 사이로 넣어 주세요.');
      if (wage && aRaw && !bRaw) return hide('단축 전 주 근로시간을 넣어 주세요.');
      if (!wage || !bRaw || !aRaw) return hide('');
      msg.textContent = '';

      var cut = Math.round((before - after) * 10) / 10;
      var h1 = Math.min(cut, c.full), h2 = Math.round((cut - h1) * 10) / 10;
      var base1 = clamp(wage, c.floor, c.cap1);
      var base2 = clamp(Math.floor(wage * c.rate2 + 1e-6), c.floor, c.cap2);
      var p1 = Math.floor(base1 * h1 / before + 1e-6);
      var p2 = h2 > 0 ? Math.floor(base2 * h2 / before + 1e-6) : 0;
      var gov = p1 + p2;
      var company = Math.floor(wage * after / before + 1e-6);
      var sum = company + gov;
      var ratio = Math.round(sum / wage * 1000) / 10;
      var capped = wage > c.cap1 || (h2 > 0 && wage * c.rate2 > c.cap2);

      var tb = $('[data-rows]');
      tb.innerHTML = '';
      function row(label, sub, amt, note, cls, capNote) {
        var tr = document.createElement('tr'); if (cls) tr.className = cls;
        var th = document.createElement('th'); th.textContent = label;
        if (sub) { var s = document.createElement('small'); s.textContent = sub; th.appendChild(s); }
        var td = document.createElement('td'); td.textContent = amt;
        if (note) { var s2 = document.createElement('small'); s2.textContent = note; if (capNote) s2.className = 'krh-cap'; td.appendChild(s2); }
        tr.appendChild(th); tr.appendChild(td); tb.appendChild(tr);
      }
      row('회사 월급 (참고)', '통상임금 × ' + hrs(after) + ' ÷ ' + hrs(before), won(company), '');
      row('정부 단축급여', '고용보험, 세금 없음', won(gov), '');
      row('최초 ' + hrs(h1) + ' 단축분', '통상임금 100%', won(p1), wage > c.cap1 ? '상한 ' + man(c.cap1) + ' 적용' : wage < c.floor ? '하한 ' + man(c.floor) + ' 적용' : '', 'krh-indent', wage > c.cap1);
      if (h2 > 0) row('나머지 ' + hrs(h2) + ' 단축분', '통상임금 80%', won(p2), wage * c.rate2 > c.cap2 ? '상한 ' + man(c.cap2) + ' 적용' : wage * c.rate2 < c.floor ? '하한 ' + man(c.floor) + ' 적용' : '', 'krh-indent', wage * c.rate2 > c.cap2);
      row('합계 예상 수입', '단축 전 ' + won(wage) + '의 ' + ratio + '%', won(sum), '', 'krh-total');
      if (months) row(months + '개월 단축급여 총액', '정부 지원분만', won(gov * months), '', 'krh-total');

      $('[data-main-label]').textContent = '주 ' + hrs(before) + ' → ' + hrs(after) + ' · 한 달 정부 단축급여';
      $('[data-big]').innerHTML = comma(gov) + '<small>원</small>';
      $('[data-badge]').textContent = h2 > 0 ? '10시간 100% + ' + hrs(h2) + ' 80%' : '줄인 ' + hrs(h1) + ' 모두 100%';
      $('[data-sub]').textContent = '회사 월급과 합쳐 월 ' + won(sum) + ' (단축 전의 ' + ratio + '%) · ' + c.basis;

      var lines = [
        '단축 시간 = ' + hrs(before) + ' − ' + hrs(after) + ' = 주 ' + hrs(cut) + (h2 > 0 ? ' (최초 10시간 + 나머지 ' + hrs(h2) + ')' : ' (10시간 이하라 모두 100%)'),
        '최초 ' + hrs(h1) + '분 = ' + man(base1) + (wage !== base1 ? '(' + (wage > base1 ? '상한' : '하한') + ')' : '') + ' × ' + h1 + ' ÷ ' + before + ' = ' + won(p1)
      ];
      if (h2 > 0) lines.push('나머지 ' + hrs(h2) + '분 = ' + man(base2) + (Math.floor(wage * c.rate2 + 1e-6) !== base2 ? '(' + (base2 === c.cap2 ? '상한' : '하한') + ')' : '(통상임금 80%)') + ' × ' + h2 + ' ÷ ' + before + ' = ' + won(p2));
      lines.push('회사 월급(참고) = ' + won(wage) + ' × ' + after + ' ÷ ' + before + ' = ' + won(company));
      lines.push('기준금액 상한: 최초 10시간분 ' + man(c.cap1) + ', 나머지 ' + man(c.cap2) + ' · 하한 ' + man(c.floor) + (capped ? ' (상한 적용됨)' : ''));
      var box = $('[data-formula]');
      box.innerHTML = '';
      lines.forEach(function (t) { var p = document.createElement('p'); p.textContent = t; box.appendChild(p); });
      $('[data-long-note]').hidden = !(months > 12);

      lastText = '[육아기 근로시간 단축 급여 계산 결과] ' + c.basis + '\n월 통상임금: ' + won(wage) + '\n근로시간: 주 ' + hrs(before) + ' → ' + hrs(after) + ' (주 ' + hrs(cut) + ' 단축)' +
        '\n회사 월급(참고): ' + won(company) + '\n정부 단축급여: 월 ' + won(gov) + ' (최초 ' + hrs(h1) + '분 ' + won(p1) + (h2 > 0 ? ' + 나머지 ' + hrs(h2) + '분 ' + won(p2) : '') + ')' +
        '\n합계 예상 수입: 월 ' + won(sum) + ' (단축 전의 ' + ratio + '%)' + (months ? '\n' + months + '개월 단축급여 총액: ' + won(gov * months) : '');
      result.classList.add('krh-show');
    }

    wageI.addEventListener('input', function () {
      var v = wageI.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 10);
      wageI.value = v ? comma(v) : '';
      calc();
    });
    [beforeI, afterI].forEach(function (inp) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/[^\d.]/g, '').replace(/(\..*)\./g, '$1').slice(0, 4);
        if (v !== inp.value) inp.value = v;
        syncChips(); calc();
      });
    });
    monthsI.addEventListener('input', function () {
      var v = monthsI.value.replace(/\D/g, '').slice(0, 2);
      if (v !== monthsI.value) monthsI.value = v;
      syncChips(); calc();
    });

    function syncChips() {
      $$('[data-a]').forEach(function (b) { b.classList.toggle('krh-on', b.getAttribute('data-a') === afterI.value); });
      $$('[data-m]').forEach(function (b) { b.classList.toggle('krh-on', b.getAttribute('data-m') === monthsI.value); });
    }
    $$('[data-a]').forEach(function (b) { b.addEventListener('click', function () { afterI.value = b.getAttribute('data-a'); syncChips(); calc(); }); });
    $$('[data-m]').forEach(function (b) { b.addEventListener('click', function () { monthsI.value = b.getAttribute('data-m'); syncChips(); calc(); }); });

    function setYear(y) {
      year = y;
      $$('[data-year]').forEach(function (b) { var on = b.getAttribute('data-year') === y; b.classList.toggle('krh-on', on); b.setAttribute('aria-pressed', on); });
      $('[data-basis]').textContent = R[y].basis;
      var n = $('[data-year-note]'); n.textContent = R[y].note; n.hidden = !R[y].note;
      calc();
    }
    $$('[data-year]').forEach(function (b) { b.addEventListener('click', function () { setYear(b.getAttribute('data-year')); }); });

    $('[data-reset]').addEventListener('click', function () {
      wageI.value = afterI.value = '';
      beforeI.value = '40'; monthsI.value = '12';
      syncChips(); setYear('2026');
      hide(''); wageI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    syncChips();
    setYear('2026');
  })();
  </script>
</div>
