        ? '신고서의 증여재산공제 금액이에요(혼인·출산 공제는 빼고). 조부모 등 다른 직계존속에게 받으며 쓴 공제도 더해 넣어요. 한도를 같이 쓰기 때문이에요.'
        : '신고했다면 신고서의 증여재산공제 금액이에요. 같은 관계의 다른 친족에게 받으며 쓴 공제도 더해 넣어요.';
    }

    function hide(text, bad) {
      result.classList.remove('kgt-show');
      msg.textContent = text || '';
      $$('.kgt-in').forEach(function (i) { i.classList.toggle('kgt-bad', !!bad && bad.indexOf(i) >= 0); });
    }

    function calc() {
      sync();
      var amt = +digits(amtI.value);
      $$('.kgt-chip').forEach(function (c) { c.classList.toggle('kgt-on', +c.dataset.v === amt); });
      amtRead.textContent = amt ? '= ' + korean(amt) : AMT_HINT;
      if (digits(amtI.value).length > 13) return hide('금액이 너무 커요. 다시 확인해 주세요.', [amtI]);
      if (!amtI.value) return hide('');
      if (!amt) return hide('이번에 받는 돈을 1원 이상 넣어 주세요.', [amtI]);
      var d = parseDate(dateI.value);
      if (!dateI.value) return hide('증여일을 넣어 주세요.', [dateI]);
      if (!d || d.getFullYear() < 2000 || d.getFullYear() > 2100) return hide('증여일을 다시 확인해 주세요.', [dateI]);

      var mused = 0;
      if (st.rel === 'asc' && st.mar !== 'none') {
        mused = +digits(musedI.value);
        if (mused > MARRIAGE_CAP) return hide('혼인·출산 공제는 평생 1억 원까지라 그보다 많이 받을 수 없어요.', [musedI]);
      }
      var pamt = 0, pded = 0, ptax = null;
      if (st.prev) {
        pamt = +digits(pamtI.value); pded = +digits(pdedI.value);
        if (digits(pamtI.value).length > 13) return hide('이전에 받은 돈이 너무 커요. 다시 확인해 주세요.', [pamtI]);
        if (!pamtI.value) return hide('10년 안에 같은 사람에게 받은 돈을 넣어 주세요. 없으면 ‘없어요’를 눌러요.', [pamtI]);
        // 그때 쓴 공제 > 그때 받은 돈: 다른 직계존속 등에게 쓴 공제가 섞인 경우라 허용(한도만 확인)
        var cap = st.rel === 'asc' ? (st.adult ? CAP.asc : CAP.ascMinor) : CAP[st.rel];
        if (pded > cap) return hide('그때 쓴 공제가 공제 한도(' + korean(cap) + ')보다 커요. 다시 확인해 주세요.', [pdedI]);
        if (ptaxI.value !== '') {
          ptax = +digits(ptaxI.value);
          if (ptax > pamt) return hide('그때 낸 증여세가 받은 돈보다 커요. 다시 확인해 주세요.', [ptaxI]);
        }
      }

      var o = { rel: st.rel, adult: st.adult, skip: st.skip, amt: amt, mar: st.mar, mused: mused, prev: st.prev, pamt: pamt, pded: pded, ptax: ptax, ontime: st.ontime };
      var r = compute(o), dl = deadline(d);
      hide('');

      $('[data-big]').innerHTML = comma(r.pay) + '<small>원</small>';
      $('[data-big-label]').textContent = st.ontime ? '내야 할 증여세 (기한 내 신고)' : '내야 할 증여세 (가산세 별도)';
      $('[data-sub]').innerHTML = '<span class="kgt-nw">과세표준 ' + won(r.base) + '</span> · <span class="kgt-nw">이번 증여액의 ' +
        (Math.round(r.pay / amt * 1000) / 10).toLocaleString('ko-KR') + '%</span>';

      var free = $('[data-free]');
      free.classList.remove('kgt-warn');
      if (r.pay === 0 && r.base < MIN_BASE && r.base > 0) {
        free.innerHTML = '과세표준이 50만 원 미만이라 증여세를 매기지 않아요(과세최저한). 그래도 신고해 두면 나중에 자금 출처를 설명하기 쉬워요.';
      } else if (r.pay === 0) {
        free.innerHTML = '공제 안에 들어가서 <b>낼 세금이 없어요.</b> 세금이 없어도 신고해 두면 나중에 자금 출처를 설명하기 쉽고, 10년 공제를 쓴 기록이 남아요.';
      } else {
        free.innerHTML = '이번 증여에 쓸 수 있는 공제는 <b>' + won(r.dNew + r.mar) + '</b>이었어요. 공제를 넘는 금액에 세금이 붙어요.';
      }
      var due = $('[data-due]');
      due.innerHTML = '신고·납부 기한: <b class="kgt-nw">' + fmt(dl.date) + '</b>까지' +
        (dl.moved ? ' <span class="kgt-nw">(원래 ' + fmt(dl.raw) + ', 휴일이라 다음 날)</span>' : '') +
        '. 증여일이 속한 달의 말일부터 3개월 안에 주소지 세무서나 홈택스로 신고해요.' +
        (r.pay > 1e7 ? ' 납부할 세금이 1천만 원을 넘으면 2개월 안에 나눠 낼 수 있어요(분납).' : '') +
        (!st.ontime ? ' <b>기한을 넘기면 신고세액공제 3%가 없고, 무신고가산세(20%)와 납부지연가산세(하루 0.022%)가 더 붙어요.</b>' : '');
      due.classList.toggle('kgt-warn', !st.ontime);

      var set = function (k, v) { root.querySelector('[data-r="' + k + '"]').textContent = v; };
      var row = function (k, show) { root.querySelector('[data-row="' + k + '"]').hidden = !show; };
      set('amt', won(amt));
      row('prev', st.prev); set('pamt', '+' + won(r.pamt));
      set('total', won(r.total));
      var capName = { asc: st.adult ? '직계존속 → 성년 자녀 5천만 원' : '직계존속 → 미성년 자녀 2천만 원', spouse: '배우자 6억 원', desc: '직계비속 → 부모 5천만 원', kin: '기타 친족 1천만 원', none: '친족 아님 0원' }[st.rel];
      set('dedlab', '10년 한도 ' + capName + (st.prev ? ' (이전 ' + comma(r.dPrev) + ' + 이번 ' + comma(r.dNew) + ')' : ''));
      set('ded', '−' + won(r.ded));
      row('mar', r.marOk); set('mar', '−' + won(r.mar));
      set('base', won(r.base));
      set('rate', r.base < MIN_BASE ? '과세표준 50만 원 미만 → 0원' : '과세표준 × ' + pct(r.rate) + (r.prog ? ' − ' + korean(r.prog).replace('원', ' 원') : ''));
      set('tax', won(r.tax));
      row('skip', st.rel === 'asc' && st.skip); set('skiplab', '산출세액 × ' + pct(r.sr || SKIP)); set('skip', '+' + won(r.skip));
      row('paid', st.prev);
      set('paidlab', (r.paidAuto ? '이전 증여 세액 자동 계산 ' : '입력한 세액 ') + comma(r.paidRaw) + '원' + (r.paid < r.paidRaw ? ', 한도 적용' : ''));
      set('paid', '−' + won(r.paid));
      set('credlab', st.ontime ? '(산출세액 + 할증 − 기납부세액) × 3%' : '기한 넘김 → 0원');
      set('cred', '−' + won(r.cred));
      set('pay', won(r.pay));

      var f = [];
      f.push('과세표준 = ' + comma(r.total) + ' − ' + comma(r.ded) + (r.marOk ? ' − ' + comma(r.mar) : '') + ' = <b>' + comma(r.base) + '원</b>');
      if (r.base >= MIN_BASE) f.push('산출세액 = ' + comma(r.base) + ' × ' + pct(r.rate) + (r.prog ? ' − ' + comma(r.prog) : '') + ' = ' + comma(r.tax) + '원');
      if (r.skip) f.push('할증 = ' + comma(r.tax) + ' × ' + pct(r.sr) + ' = ' + comma(r.skip) + '원');
      f.push('납부세액 = ' + comma(r.tax) + (r.skip ? ' + ' + comma(r.skip) : '') + (st.prev ? ' − ' + comma(r.paid) : '') + ' − ' + comma(r.cred) + ' = <b>' + comma(r.pay) + '원</b>');
      $('[data-formula]').innerHTML = f.map(function (x) { return '<p>' + x + '</p>'; }).join('');

      result.classList.add('kgt-show');

      lastText = '[증여세 계산 결과]\n관계: ' + REL_NAME[st.rel] + (st.rel === 'asc' ? ' / ' + (st.adult ? '성년' : '미성년') + ' / ' + (st.skip ? '조부모(세대생략)' : '부모') : '') +
        '\n이번 증여재산: ' + won(amt) + '\n증여일: ' + fmt(d) +
        (st.prev ? '\n10년 합산 증여재산: ' + won(r.pamt) : '') +
        '\n증여세 과세가액: ' + won(r.total) + '\n증여재산공제: ' + won(r.ded) +
        (r.marOk ? '\n혼인·출산 공제: ' + won(r.mar) : '') +
        '\n과세표준: ' + won(r.base) + '\n산출세액: ' + won(r.tax) +
        (r.skip ? '\n세대생략 할증(' + pct(r.sr) + '): ' + won(r.skip) : '') +
        (st.prev ? '\n기납부세액공제: ' + won(r.paid) : '') +
        '\n신고세액공제: ' + won(r.cred) + '\n납부할 증여세: ' + won(r.pay) +
        '\n신고·납부 기한: ' + fmt(dl.date) + (st.ontime ? '' : ' (기한 넘김, 가산세 별도)') +
        '\n※ 참고용 계산이며 세무 자문이 아니에요.';
    }

    function money(i, max) {
      i.addEventListener('input', function () {
        var v = digits(i.value).slice(0, max || 14);
        i.value = v ? comma(+v) : '';
        calc();
      });
    }
    [amtI, musedI, pamtI, pdedI, ptaxI].forEach(function (i) { money(i); });
    dateI.addEventListener('input', calc); dateI.addEventListener('change', calc);

    $$('[data-rel]').forEach(function (b) { b.addEventListener('click', function () { st.rel = b.dataset.rel; calc(); }); });
    $$('[data-adult]').forEach(function (b) { b.addEventListener('click', function () { st.adult = b.dataset.adult === '1'; calc(); }); });
    $$('[data-skip]').forEach(function (b) { b.addEventListener('click', function () { st.skip = b.dataset.skip === '1'; calc(); }); });
    $$('[data-mar]').forEach(function (b) { b.addEventListener('click', function () { st.mar = b.dataset.mar; calc(); }); });
    $$('[data-prev]').forEach(function (b) { b.addEventListener('click', function () { st.prev = b.dataset.prev === '1'; calc(); }); });
    $$('[data-ontime]').forEach(function (b) { b.addEventListener('click', function () { st.ontime = b.dataset.ontime === '1'; calc(); }); });

    $('[data-reset]').addEventListener('click', function () {
      amtI.value = musedI.value = pamtI.value = pdedI.value = ptaxI.value = '';
      dateI.value = iso(today());
      st = { rel: 'asc', adult: true, skip: false, mar: 'none', prev: false, ontime: true };
      hide(''); calc(); amtI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    calc();
  })();
  </script>
</div>
