      if (sum === 0) return hide('두 분의 소득이 모두 0이면 분담비율을 계산할 수 없어요.');

      var ci = incIdx(sum), total = 0, rows = '', copyRows = '';
      list.forEach(function (age, k) {
        var g = AGES[ageIdx(age)], c = g.row[ci];
        var avg = c[0] * 1000, lo = c[1] * 1000, hi = c[2] * 1000;
        var range = won(lo) + (hi ? ' ~ ' + won(hi) : ' 이상');
        total += avg;
        rows += '<div class="kcs-item"><p class="kcs-item-k">' + ORD[k] + ' (만 ' + age + '세)<span>' + g.name + ' 구간</span></p>' +
          '<p class="kcs-item-v">' + won(avg) + '<span>범위 ' + range + '</span></p></div>';
        copyRows += '\n' + ORD[k] + '(만 ' + age + '세, ' + g.name + '): ' + won(avg) + ' (범위 ' + range + ')';
      });
      var ratio = b / sum, pay = Math.round(total * b / sum);
      rows += '<div class="kcs-item kcs-total"><p class="kcs-item-k">표준양육비 합계<span>부모 합산소득 ' + man(sum) + ' → ' + INC[ci] + ' 구간</span></p>' +
        '<p class="kcs-item-v">' + won(total) + '<span>자녀 ' + n + '명</span></p></div>' +
        '<div class="kcs-item"><p class="kcs-item-k">비양육자 분담비율<span>' + man(b) + ' ÷ ' + man(sum) + '</span></p><p class="kcs-item-v">' + pct(ratio) + '</p></div>';

      $('[data-list]').innerHTML = rows;
      $('[data-pay]').textContent = pay.toLocaleString('ko-KR');
      $('[data-pay-sub]').textContent = '자녀 1명당 평균 약 ' + won(Math.round(pay / n)) + ' · 양육자 부담분 ' + won(total - pay);
      $('[data-formula]').innerHTML = '<b>계산식</b> 표준양육비 합계 ' + won(total) + ' × 비양육자 소득 비율(' + man(b) + ' ÷ ' + man(sum) + ') = <b>' + won(pay) + '</b>';
      var adj = $('[data-adj]');
      if (n === 1) { adj.hidden = false; adj.textContent = '기준표는 자녀 2명 가구 기준이에요. 자녀가 1명이면 표 금액보다 가산될 수 있어요(얼마나 조정할지는 협의나 법원이 정해요).'; }
      else if (n >= 3) { adj.hidden = false; adj.textContent = '기준표는 자녀 2명 가구 기준이에요. 자녀가 3명 이상이면 표 금액보다 감산될 수 있어요(얼마나 조정할지는 협의나 법원이 정해요).'; }
      else adj.hidden = true;
      msg.textContent = '';
      result.classList.add('kcs-show');

      lastText = '[양육비 계산 결과 - 2021 양육비 산정기준표]\n양육자 소득: ' + man(a) + ' / 비양육자 소득: ' + man(b) +
        '\n부모 합산소득: ' + man(sum) + ' (' + INC[ci] + ' 구간)' + copyRows +
        '\n표준양육비 합계: ' + won(total) + '\n비양육자 분담비율: ' + pct(ratio) +
        '\n비양육자 월 부담액: ' + won(pay) + '\n※ 참고용이며 실제 양육비는 개별 사정을 고려해 협의하거나 법원이 정해요.';
    }

    function setN(k) {
      n = k;
      $$('[data-n]').forEach(function (c) { c.classList.toggle('kcs-on', +c.dataset.n === k); c.setAttribute('aria-pressed', +c.dataset.n === k); });
      fields.forEach(function (f, i) { f.hidden = i >= k; });
      calc();
    }
    $$('[data-n]').forEach(function (c) { c.addEventListener('click', function () { setN(+c.dataset.n); }); });

    [incA, incB].forEach(function (inp) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 6);
        inp.value = v ? (+v).toLocaleString('ko-KR') : '';
        calc();
      });
    });
    ages.forEach(function (inp) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 2);
        if (v !== inp.value) inp.value = v;
        calc();
      });
    });

    $('[data-reset]').addEventListener('click', function () {
      incA.value = incB.value = ''; ages.forEach(function (x) { x.value = ''; }); setN(1); hide(''); incA.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });
    setN(1);
  })();
  </script>
</div>
